// Following: https://youtu.be/u5HAYVHsasc
// Shadertoy for absolute beginners tutorials

vec3 circ(vec2 uv, vec2 pos, float r, float blend, vec3 c)
{
    uv -= pos;
    float d = length(uv);
    float mx = smoothstep(r, r-blend, d);
    return mx * c;
}

float band(float t, float start, float end, float blur)
{
    float step1 = smoothstep(start - blur, start + blur, t);
    float step2 = smoothstep(end + blur, end - blur, t);
    return step1*step2;
}

float rect(vec2 uv, vec2 p, float w, float h, float blur)
{
    uv -= p;

    float left = 0.0;
    float right = w;
    float bottom = 0.0;
    float top = h;

    float lr_band = band(uv.x, left, right, blur);
    float bt_band = band(uv.y, bottom, top, blur);
    return lr_band * bt_band;
}

float rect(vec2 uv, float left, float right, float bottom, float top, float blur)
{
    float lr_band = band(uv.x, left, right, blur);
    float bt_band = band(uv.y, bottom, top, blur);
    return lr_band * bt_band;
}

float remap01(vec2 r, float t)
{
    return (t - r.x) / (r.y - r.x);
}

float remap(vec2 r1, vec2 r2, float t) {
    return remap01(r1, t) * (r2.y - r2.x) + r2.x;
}

